                      in: "$$matchedSpec.is_featured",
                    },
                  },
                  false,
                ],
              },
            },
          },
        },
      },
    },
    {
      $sort: hasLocation ? { distanceKm: 1 } : { name: 1 },
    },
  ]);
};

